open Raster2
let ok=function Ok x->x|Error _->failwith"offscreen error"
let ir frame width height=ok(Render_ir.create[|Clear(Int32.of_int(((frame land 255)lsl 24)lor 0xff));Geometry{vertices=[|0.;0.;float(width-1);0.;0.;float(height-1)|];indices=[|0;1;2|];color=0x00ff00ffl}|])
let render frame width height=let target=ok(Offscreen.create~depth:true~width~height())in let view=ok(Offscreen.view target)in ok(Offscreen.render view~lookup:(fun _->None)(ir frame width height));let capture=ok(Offscreen.capture view)in ok(Offscreen.release_view view);ok(Offscreen.destroy target);capture.pixels
let ()=List.iter(fun frame->let expected=render frame 8 6 in let workers=Array.init 4(fun _->Domain.spawn(fun()->render frame 8 6))in Array.iter(fun worker->assert(Domain.join worker=expected))workers)[1;2;60;600];let target=ok(Offscreen.create~width:4~height:3())in let stale=ok(Offscreen.view target)in ok(Offscreen.resize target~width:7~height:5);(match Offscreen.capture stale with Error Offscreen.Stale_generation->()|_->failwith"stale capture");(match Offscreen.destroy target with Error(Offscreen.Live_views 1)->()|_->failwith"destroyed before view");ok(Offscreen.release_view stale);let fresh=ok(Offscreen.view target)in assert((ok(Offscreen.capture fresh)).width=7);ok(Offscreen.release_view fresh);ok(Offscreen.destroy target);let baseline=Offscreen.counters()in for _=1 to 100_000 do let target=ok(Offscreen.create~width:1~height:1())in let view=ok(Offscreen.view target)in ok(Offscreen.release_view view);ok(Offscreen.destroy target)done;assert(Offscreen.counters()=baseline);print_endline"Raster2 deterministic offscreen lifecycle passed"
